changeSet.sql:
-- Colonne nature_avoir dans avoirs
ALTER TABLE IF EXISTS avoirs 
    ADD COLUMN IF NOT EXISTS nature_avoir VARCHAR(50) DEFAULT 'RETOUR_MARCHANDISE';

-- Colonne designation dans lignes_avoir
ALTER TABLE IF EXISTS lignes_avoir 
    ADD COLUMN IF NOT EXISTS designation VARCHAR(255);

-- Rendre produit_id optionnel dans lignes_avoir pour les avoirs commerciaux / remises forfaitaires
ALTER TABLE IF EXISTS lignes_avoir 
    ALTER COLUMN produit_id DROP NOT NULL;

-- Index sur facture_origine_id pour optimiser les contrôles anti-dépassement
CREATE INDEX IF NOT EXISTS idx_avoirs_facture_origine ON avoirs(facture_origine_id);
